$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);\TNL\Admin\Users::init($db);\TNL\Admin\Settings::set($db,'company_domain','company.test');foreach(['alice','bob'] as $name)\TNL\Admin\Users::create($db,['username'=>$name,'display_name'=>$name,'domain'=>'company.test','password'=>'test-password-only']);$dir=sys_get_temp_dir().'/tnl-sender-'.bin2hex(random_bytes(6));mkdir($dir,0700);$store=new ExternalAccount($db,$dir);$base=['email'=>'alice@company.test','imap_host'=>'imap.company.test','smtp_host'=>'smtp.company.test','smtp_username'=>'company-user','smtp_password'=>'company-smtp'];$store->save('employee:1',$base,'company-imap');$store->save('admin:1',array_replace($base,['email'=>'public@company.test']),'public-imap');$boxes=new Mailboxes($db);$box=$boxes->assign(0,1,'Company',$base,'box-password',$store);$personal=new PersonalAccounts($db,$store);$personalInput=['email'=>'alice@outside.test','imap_host'=>'imap.outside.test','smtp_host'=>'smtp.outside.test','smtp_username'=>'personal-user','smtp_password'=>'personal-smtp','smtp_port'=>465];$one=$personal->save(0,'employee:1','Personal',$personalInput,'personal-imap');$two=$personal->save(0,'employee:1','Second',array_replace($personalInput,['email'=>'other@elsewhere.test','smtp_host'=>'smtp.elsewhere.test']),'second-imap');$who=['principal'=>'employee:1','role'=>'employee','id'=>1];$owner='personal:'.$one;
senderCheck(AccountAccess::externalOwner($db,$store,$who,[],$owner)===$owner,'reopening mail preserves personal mailbox despite company assignments');senderCheck(AccountAccess::externalOwner($db,$store,$who,['account'=>'legacy'],$owner)==='employee:1','explicit primary selection overrides remembered personal account');senderCheck(AccountAccess::externalOwner($db,$store,$who,['account'=>'box:'.$box],$owner)==='mailbox:'.$box,'explicit business selection remains possible');senderCheck(AccountAccess::externalOwner($db,$store,$who,['account'=>'personal:'.$two],$owner)==='personal:'.$two,'personal account changes remain explicit');senderDenied(fn()=>AccountAccess::externalOwner($db,$store,['principal'=>'employee:2','role'=>'employee','id'=>2],[],$owner),'remembered mailbox cannot bypass ownership');senderDenied(fn()=>AccountAccess::externalOwner($db,$store,$who,['personal'=>$one,'box'=>$box]),'contradictory sender selections fail closed');senderDenied(fn()=>$store->sender($owner,'alice@company.test'),'stale or mismatched compose identity cannot switch SMTP');
final class PersonalSmtpProbe extends \PHPMailer\PHPMailer\SMTP {public bool $open=false;public string $endpoint='';public array $auth=[];public string $from='';public function connect($host,$port=null,$timeout=30,$options=[]){$this->open=true;$this->endpoint=$host.':'.$port;return true;}public function connected(){return $this->open;}public function hello($host=''){return true;}public function getServerExt($name){return $name==='AUTH'?['LOGIN']:false;}public function authenticate($username,$password,$authtype=null,$OAuth=null){$this->auth=[$username,$password];return true;}public function mail($from){$this->from=$from;return true;}public function recipient($address,$dsn=''){return true;}public function data($msg_data){return true;}public function quit($close_on_error=true){$this->open=false;return true;}public function close(){$this->open=false;}}
$account=$store->sender($owner,'alice@outside.test');$probe=new PersonalSmtpProbe();ExternalMail::send($account,'client@recipient.test','SMTP scope','Test body',$probe);senderCheck($probe->endpoint==='ssl://smtp.outside.test:465'&&$probe->auth===['personal-user','personal-smtp']&&$probe->from==='alice@outside.test','SMTP host, credentials and From belong to personal account, never company or public account');$fallbackProbe=new PersonalSmtpProbe();$delivery=\TNL\Mail\Dispatch::send($db,'employee:1',1,str_repeat('a',48),'bob@company.test, sales@company.test','','Company routing','Body',true,$account,$owner,$dir,null,[],'new',fn($to,$extra,$cc)=>ExternalMail::send($account,$to,'Company routing','Body',$fallbackProbe,[],'plain',$extra,$cc));senderCheck($delivery['state']==='completed'&&$delivery['results'][0]['route']==='internal'&&$delivery['results'][1]['route']==='smtp'&&$fallbackProbe->endpoint==='ssl://smtp.outside.test:465'&&$fallbackProbe->from==='alice@outside.test','unassigned company address uses personal sender SMTP while assigned colleague stays internal');senderCheck(AccountAccess::personal($db,$owner,$account)&&!AccountAccess::personal($db,'mailbox:'.$box,$store->load('mailbox:'.$box)),'notice distinguishes personal and assigned business accounts');ob_start();\TNL\UI\SenderNotice::render(true);$notice=ob_get_clean();senderCheck(str_contains($notice,'podría guardar una copia')&&str_contains($notice,'cuenta empresarial')&&str_contains($notice,'reception-mail.php'),'personal notice explains copies and business reception alternative');ob_start();\TNL\UI\SenderNotice::render(false);senderCheck(ob_get_clean()==='','business editor has no personal-account warning');$context=['principal'=>'employee:1','owner'=>$owner,'email'=>'alice@outside.test','created'=>time()];$resolved=AccountAccess::composeSender($db,$store,$who,$context);senderCheck($resolved['owner']===$owner&&$resolved['account']['smtp_host']==='smtp.outside.test','posting compose form uses its bound account independently of current folder or tab');$primaryInput=array_replace($personalInput,['email'=>'alice@praxma.org','smtp_host'=>'praxma.org']);$store->save('employee:1',$primaryInput,'primary-personal-imap');$primaryContext=['principal'=>'employee:1','owner'=>'employee:1','email'=>'alice@praxma.org','created'=>time()];$resolved=AccountAccess::composeSender($db,$store,$who,$primaryContext);senderCheck($resolved['account']['smtp_host']==='praxma.org'&&AccountAccess::personal($db,'employee:1',$resolved['account']),'personal primary account from another domain sends with its saved SMTP');senderCheck(AccountAccess::personal($db,'mailbox:'.$box,['email'=>'assigned@praxma.org']),'personal classification depends only on domain, including assigned accounts');senderDenied(fn()=>AccountAccess::composeSender($db,$store,['principal'=>'employee:2','role'=>'employee','id'=>2],$primaryContext),'compose form cannot cross logged-in identities');senderDenied(fn()=>AccountAccess::composeSender($db,$store,$who,array_replace($context,['created'=>time()-1900])),'expired form cannot send');$personal->remove($one,'employee:1');senderDenied(fn()=>AccountAccess::externalOwner($db,$store,$who,[],$owner),'unlinked personal account does not fall back silently to company');senderDenied(fn()=>$store->sender($owner,'alice@outside.test'),'missing account never falls back to public SMTP');
